const cfg = {
  spreadsheet_id: 'YOUR_GOOGLE_SHEET_ID',
  cv_active_folder_id: 'YOUR_CV_ACTIVE_FOLDER_ID',
  timezone: 'UTC',
  // Keep the same twelve sheet names in every workflow.
  monthly_sheets: ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"],
};
if (cfg.spreadsheet_id.startsWith('YOUR_')) throw new Error('Configure spreadsheet_id in Config.');
new Intl.DateTimeFormat('en-US', {timeZone: cfg.timezone});
if (cfg.cv_active_folder_id.startsWith('YOUR_')) throw new Error('Configure cv_active_folder_id in Config.');
return [{json:cfg}];

const response = $json ?? {};

const valueRanges = Array.isArray(response.valueRanges)
  ? response.valueRanges
  : [];

const jobs = [];

for (const range of valueRanges) {
  const rangeName = String(range.range ?? '');

  const sheetMatch = rangeName.match(/^'?([^'!]+)'?!/);

  const targetSheet = sheetMatch
    ? sheetMatch[1]
    : '';

  const rows = Array.isArray(range.values)
    ? range.values
    : [];

  // Linha 1 = cabeçalho
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i] ?? [];

    const qualified = String(row[19] ?? '').trim();
    const coverLetter = String(row[20] ?? '').trim();
    const description = String(row[11] ?? '').trim();

    const isQualified =
      qualified.toLowerCase() === 'yeap';

    const hasNoCoverLetter =
      coverLetter === '';

    const hasDescription =
      description !== '';

    if (!isQualified) {
      continue;
    }

    if (!hasNoCoverLetter) {
      continue;
    }

    if (!hasDescription) {
      continue;
    }

    jobs.push({
      json: {
        target_sheet: targetSheet,
        row_number: i + 1,

        job_id: String(row[0] ?? ''),
        status: String(row[1] ?? ''),
        date_scraped: String(row[2] ?? ''),
        source: String(row[3] ?? ''),
        search_keyword: String(row[4] ?? ''),
        date_posted: String(row[5] ?? ''),
        title: String(row[6] ?? ''),
        work_mode: String(row[7] ?? ''),
        url: String(row[8] ?? ''),
        company_name: String(row[9] ?? ''),
        location: String(row[10] ?? ''),
        description,
        language: String(row[12] ?? ''),
        payment: String(row[13] ?? ''),
        time_type: String(row[14] ?? ''),
        job_type: String(row[15] ?? ''),
        experience: String(row[16] ?? ''),
        salary: String(row[17] ?? ''),
        match: String(row[18] ?? ''),
        qualified,
        cover_letter: coverLetter,
        notes: String(row[21] ?? ''),
        interview_at: String(row[22] ?? ''),
        invite_meet: String(row[23] ?? ''),
        attended:
          row[24] === true ||
          String(row[24] ?? '').toLowerCase() === 'true'
      }
    });
  }
}

return jobs;

const cvSource = $json ?? {};
const cvText = String(
  cvSource.text ??
  cvSource.content ??
  cvSource.data ??
  cvSource.extractedText ??
  ''
).replace(/\r/g, '')
 .replace(/[ \t]+/g, ' ')
 .replace(/\n{3,}/g, '\n\n')
 .trim();

if (!cvText) {
  throw new Error('CV text is empty. Check the Google Drive and Extract CV Text nodes.');
}

return $('Filter Qualified Jobs').all().map(item => ({
  json: {
    ...item.json,
    cv_text: cvText
  }
}));

