const job = $('Prepare Cover Letter Prompt').item.json;

const raw =
  $json?.choices?.[0]?.message?.content ??
  $json?.text ??
  $json?.output ??
  $json?.response ??
  '';

const coverLetter = String(raw ?? '')
  .trim()
  .replace(/^```(?:text|markdown)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

if (!coverLetter) {
  throw new Error('Groq returned an empty cover letter.');
}

return {
  json: {
    ...job,
    cover_letter: coverLetter
  }
};

const job = $('Prepare Cover Letter Prompt').item.json;

const generatedMessage =
  $json?.choices?.[0]?.message?.content ??
  '';

const cvText = String(job.cv_text ?? '').trim();
const language = String(job.language ?? '').trim();

if (!generatedMessage.trim()) {
  throw new Error('Generated recruiter message is empty.');
}

let languageRule = '';

if (language === 'Portuguese') {
  languageRule = `
Keep the final message in natural Brazilian Portuguese.
Keep it friendly, professional and appropriate for a LinkedIn recruiter DM.
`;
} else if (language === 'English') {
  languageRule = `
Keep the final message in natural professional English.
Keep it friendly, professional and appropriate for a LinkedIn recruiter DM.
`;
} else {
  languageRule = `
Keep the same language as the original message.
`;
}

const factCheckPrompt = `
You are a strict factual editor.

Your ONLY task is to remove unsupported claims from a recruiter message.

The CANDIDATE CV below is the ONLY source of truth.

==================================================
STRICT RULES
==================================================

Review every factual statement about the candidate.

A claim may remain ONLY if it is explicitly supported by the CV.

When a specific project is mentioned:
- use ONLY technologies, actions and results written inside that project's own CV bullets;
- do NOT attach CORE SKILLS to that project;
- do NOT combine information from different projects;
- do NOT infer architecture, scale, purpose or implementation details.

Do NOT invent anything.

Do NOT add new candidate facts.

Do NOT add new technologies.

Do NOT add new achievements.

Do NOT add new explanations.

Do NOT improve the message by introducing factual details that were not already present.

Your editing strategy must be CONSERVATIVE:

1. Keep supported wording.
2. Delete unsupported words, phrases or sentences.
3. Make only minimal grammatical changes when deletion requires it.

If uncertain whether a claim is supported:
DELETE IT.

Examples:

If the message says a project was "fully Python-based"
but that project's CV bullets do not say Python:
remove that claim.

If the message says "several APIs"
but the project only explicitly mentions Google Workspace APIs:
remove "several APIs" rather than generalizing.

If the message says a workflow "collects video data"
but the CV only says it processes links, transcripts, metrics and comments:
use the explicit CV wording or remove the claim.

Do NOT mention the CV itself in the final message.

Never write phrases such as:
"according to my CV"
"listed in my CV"
"as stated in my CV"
"que consta no meu CV"
"que coloquei no meu CV"

==================================================
STYLE
==================================================

${languageRule}

Keep approximately the same length or shorter.

Do not turn it into a formal cover letter.

Do not add bullet points.

Return ONLY the corrected recruiter message.

==================================================
CANDIDATE CV
SOURCE OF TRUTH
==================================================

${cvText}

==================================================
MESSAGE TO REVIEW
==================================================

${generatedMessage}
`.trim();

return {
  json: {
    ...job,
    generated_message: generatedMessage,
    fact_check_prompt: factCheckPrompt
  }
};

